package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AssigneeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property assignee of observed issue ")
  void test_assignee_v_o_builder() {
    Assertions.assertFalse(AssigneeVO.nullValue().getAssignee().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AssigneeVO.tryFrom(null).getAssignee().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", AssigneeVO.from("one").getAssignee().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> AssigneeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AssigneeVO.from("one").toString());
  }
}
